RESET = "\033[0m"
BOLD = "\033[1m"
DIM = "\033[2m"
CYAN = "\033[96m"
BLUE = "\033[94m"
GREEN = "\033[92m"
YELLOW = "\033[93m"
MAGENTA = "\033[95m"
RED = "\033[91m"
WHITE = "\033[97m"

def paint(value, color):
    return f"{color}{value}{RESET}"

def clear():
    os.system("clear" if os.name != "nt" else "cls")

def line(char="─", width=68, color=CYAN):
    print(paint(char * width, color))

def center(text, width=68):
    print(text.center(width))

