def catalogue_view():
    lines = CATALOGUE.splitlines()
    page_size = 34
    total = len(lines)
    start = 0
    while True:
        clear()
        logo()
        print(paint("INTELLIGENCE LIBRARY  /  SOURCE CATALOGUE", BOLD + YELLOW))
        print(paint(f"LINES {start + 1}-{min(start + page_size, total)} OF {total}", DIM))
        line()
        for item in lines[start:start + page_size]:
            if item.startswith("===="):
                print(paint(item, CYAN))
            elif "MODULE CATALOGUE" in item or "QUICK START" in item or "PIPELINE" in item:
                print(paint(item, BOLD + YELLOW))
            else:
                print(item)
        line()
        print("[N] Next page   [P] Previous page   [Q] Return to menu")
        choice = input(paint("LIBRARY › ", CYAN)).strip().lower()
        if choice == "n" and start + page_size < total:
            start += page_size
        elif choice == "p" and start > 0:
            start = max(0, start - page_size)
        elif choice == "q":
            return

def menu():
    while True:
        clear()
        logo()
        print(paint("MAIN CONTROL PANEL", BOLD + YELLOW))
        print("  [1]  SYSTEM DASHBOARD")
        print("  [2]  OPEN INTELLIGENCE LIBRARY")
        print("  [3]  ABOUT / SAFETY INFORMATION")
        print("  [0]  EXIT HEDA")
        line()
        choice = input(paint("SELECT MODULE › ", CYAN)).strip()
        if choice == "1":
            dashboard()
            input("\nPress ENTER to return...")
        elif choice == "2":
            catalogue_view()
        elif choice == "3":
            logo()
            print(paint("HEDA — LOCAL PRESENTATION BUILD", BOLD + WHITE))
            print("The embedded source is a research-module specification.")
            print("Quantum-inspired methods here mean classical mathematical")
            print("approaches inspired by probability, optimization and graph")
            print("ideas; no quantum hardware or quantum advantage is implied.")
            print("No returns are guaranteed. Live trading is not enabled.")
            input("\nPress ENTER to return...")
        elif choice == "0":
            print(paint("\nHEDA SESSION CLOSED. GOODBYE.", CYAN))
            return
        else:
            print(paint("Invalid selection.", RED))
            time.sleep(0.8)

def main():
    try:
        if authenticate():
            boot_sequence()
            menu()
    except KeyboardInterrupt:
        print(paint("\n\nHEDA SESSION INTERRUPTED.", YELLOW))
    finally:
        print(paint("LOCAL SESSION ENDED.", DIM))

if __name__ == "__main__":
    main()
